package com.therighthon.rnr.common.block;
import com.therighthon.rnr.RNRHelpers; import net.minecraft.core.BlockPos; import net.minecraft.world.InteractionHand; import net.minecraft.world.InteractionResult; import net.minecraft.world.entity.player.Player; import net.minecraft.world.level.BlockGetter; import net.minecraft.world.level.Level; import net.minecraft.world.level.block.Block; import net.minecraft.world.level.block.state.BlockState; import net.minecraft.world.phys.BlockHitResult; import net.minecraft.world.phys.shapes.CollisionContext; import net.minecraft.world.phys.shapes.VoxelShape;
public abstract class PathHeightDeviceBlock extends Block { protected static final VoxelShape SHAPE=Block.box(0,0,0,16,15,16); protected PathHeightDeviceBlock(Properties p){super(p);} public VoxelShape getShape(BlockState s,BlockGetter g,BlockPos p,CollisionContext c){return SHAPE;} public InteractionResult use(BlockState s,Level l,BlockPos p,Player pl,InteractionHand h,BlockHitResult hit){return RNRHelpers.blockModRecipeCompatible(s,l,p,pl,h,hit);} }
